from EfiPy2 import *
from EfiPy2.MdePkg.IndustryStandard.Acpi import *

#
# Known performance tokens
#
SEC_TOK                    = "SEC"
DXE_TOK                    = "DXE"
PEI_TOK                    = "PEI"
BDS_TOK                    = "BDS"
DRIVERBINDING_START_TOK    = "DB:Start:"
DRIVERBINDING_SUPPORT_TOK  = "DB:Support:"
DRIVERBINDING_STOP_TOK     = "DB:Stop:"
LOAD_IMAGE_TOK             = "LoadImage:"
START_IMAGE_TOK            = "StartImage:"
PEIM_TOK                   = "PEIM"

#
# Misc defines
#
FPDT_RECORD_REVISION_1     = (0x01)

#
# Length field in EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER is a UINT8, thus:
#
FPDT_MAX_PERF_RECORD_SIZE  = (MAX_UINT8)

#
# FPDT Record Types
#
FPDT_GUID_EVENT_TYPE               = 0x1010
FPDT_DYNAMIC_STRING_EVENT_TYPE     = 0x1011
FPDT_DUAL_GUID_STRING_EVENT_TYPE   = 0x1012
FPDT_GUID_QWORD_EVENT_TYPE         = 0x1013
FPDT_GUID_QWORD_STRING_EVENT_TYPE  = 0x1014

#
# EDKII extended Fpdt record structures
#
FPDT_STRING_EVENT_RECORD_NAME_LENGTH  = 24

#
# FPDT Boot Performance Guid Event Record Structure
#
class FPDT_GUID_EVENT_RECORD (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Header",      EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("ProgressID",  UINT16),
    ("ApicID",      UINT32),
    ("Timestamp",   UINT64),
    ("Guid",        EFI_GUID)
  ]

#
# FPDT Boot Performance Dynamic String Event Record Structure
#
class FPDT_DYNAMIC_STRING_EVENT_RECORD (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Header",      EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("ProgressID",  UINT16),
    ("ApicID",      UINT32),
    ("Timestamp",   UINT64),
    ("Guid",        EFI_GUID),
    ("String",      CHAR8 * 1)
  ]

#
# FPDT Boot Performance Dual GUID String Event Record Structure
#
class FPDT_DUAL_GUID_STRING_EVENT_RECORD (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Header",      EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("ProgressID",  UINT16),
    ("ApicID",      UINT32),
    ("Timestamp",   UINT64),
    ("Guid1",       EFI_GUID),
    ("Guid2",       EFI_GUID),
    ("String",      CHAR8 * 1)
  ]

#
# FPDT Boot Performance GUID Qword Event Record Structure
#
class FPDT_GUID_QWORD_EVENT_RECORD (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Header",      EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("ProgressID",  UINT16),
    ("ApicID",      UINT32),
    ("Timestamp",   UINT64),
    ("Guid",        EFI_GUID),
    ("Qword",       UINT64)
  ]

#
# FPDT Boot Performance GUID Qword String Event Record Structure
#
class FPDT_GUID_QWORD_STRING_EVENT_RECORD (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Header",      EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("ProgressID",  UINT16),
    ("ApicID",      UINT32),
    ("Timestamp",   UINT64),
    ("Guid",        EFI_GUID),
    ("Qword",       UINT64),
    ("String",      CHAR8 * 1)
  ]

#
# Union of all FPDT records
#
class FPDT_RECORD (Union):
  _fields_ = [
    ("RecordHeader",          EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER),
    ("GuidEvent",             FPDT_GUID_EVENT_RECORD),
    ("DynamicStringEvent",    FPDT_DYNAMIC_STRING_EVENT_RECORD),
    ("DualGuidStringEvent",   FPDT_DUAL_GUID_STRING_EVENT_RECORD),
    ("GuidQwordEvent",        FPDT_GUID_QWORD_EVENT_RECORD),
    ("GuidQwordStringEvent",  FPDT_GUID_QWORD_STRING_EVENT_RECORD)
  ]

#
# Union of all pointers to FPDT records
#
class FPDT_RECORD_PTR (Union):
  _fields_ = [
    ("RecordHeader",          POINTER(EFI_ACPI_5_0_FPDT_PERFORMANCE_RECORD_HEADER)),
    ("GuidEvent",             POINTER(FPDT_GUID_EVENT_RECORD)),
    ("DynamicStringEvent",    POINTER(FPDT_DYNAMIC_STRING_EVENT_RECORD)),
    ("DualGuidStringEvent",   POINTER(FPDT_DUAL_GUID_STRING_EVENT_RECORD)),
    ("GuidQwordEvent",        POINTER(FPDT_GUID_QWORD_EVENT_RECORD)),
    ("GuidQwordStringEvent",  POINTER(FPDT_GUID_QWORD_STRING_EVENT_RECORD))
  ]

#
# Hob:
#   GUID - gEdkiiFpdtExtendedFirmwarePerformanceGuid;
#   Data - FPDT_PEI_EXT_PERF_HEADER + one or more FPDT records
#
class FPDT_PEI_EXT_PERF_HEADER (Structure):
  _fields_ = [
    ("SizeOfAllEntries",  UINT32),
    ("LoadImageCount",    UINT32),
    ("HobIsFull",         UINT32)
  ]

gEdkiiFpdtExtendedFirmwarePerformanceGuid = \
  EFI_GUID (0x3b387bfd, 0x7abc, 0x4cf2, ( 0xa0, 0xca, 0xb6, 0xa1, 0x6c, 0x1b, 0x1b, 0x25 ))
